#!/usr/bin/env node
// Validates that values in a .env file match expected formats.
// Prints only KEY: ok/fail/unknown — never the values themselves.
// Usage: node scripts/check-env-formats.js path/to/.env

const fs = require('fs');
const path = require('path');

const PATTERNS = [
  { name: 'AWS Access Key ID',     match: /_ACCESS_KEY_ID$/,     regex: /^AKIA[0-9A-Z]{16}$/ },
  { name: 'AWS Secret Access Key', match: /_SECRET_ACCESS_KEY$/, regex: /^[A-Za-z0-9/+=]{40}$/ },
  { name: 'Stripe Live Secret',    match: /^STRIPE_SECRET/,      regex: /^sk-live-[A-Za-z0-9]{24,}$/ },
  { name: 'Anthropic API Key',     match: /^ANTHROPIC_API_KEY$/, regex: /^sk-ant-[A-Za-z0-9_-]{20,}$/ },
  { name: 'Postgres URL',          match: /^DATABASE_URL$/,      regex: /^postgres(ql)?:\/\/.+/ },
];

const file = process.argv[2];
if (!file) { console.error('Usage: check-env-formats.js <path>'); process.exit(2); }

const lines = fs.readFileSync(path.resolve(file), 'utf8').split('\n');
for (const line of lines) {
  const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.+?)\s*$/);
  if (!m) continue;
  const [, key, value] = m;
  const rule = PATTERNS.find(p => p.match.test(key));
  if (!rule) { console.log(`${key}: unknown (no rule)`); continue; }
  console.log(`${key}: ${rule.regex.test(value) ? 'ok' : 'fail'} (${rule.name})`);
}

