// Startup environment validation.
// Validates presence and format of required secrets WITHOUT logging their values.
// On failure, reports only the variable name and which check failed.

const VALIDATORS = {
  DATABASE_URL: {
    description: 'Postgres connection URI',
    test: (v) => /^postgres(ql)?:\/\/.+/.test(v),
    expected: 'postgres:// or postgresql:// URI',
  },
  AWS_ACCESS_KEY_ID: {
    description: 'AWS access key ID',
    // AKIA = long-lived IAM user key; ASIA = temporary STS token
    test: (v) => /^(AKIA|ASIA)[A-Z0-9]{16}$/.test(v),
    expected: '20-char key starting with AKIA or ASIA',
  },
  AWS_SECRET_ACCESS_KEY: {
    description: 'AWS secret access key',
    test: (v) => /^[A-Za-z0-9/+=]{40}$/.test(v),
    expected: '40-char base64-ish string',
  },
  ANTHROPIC_API_KEY: {
    description: 'Anthropic API key',
    test: (v) => /^sk-ant-[A-Za-z0-9_-]+$/.test(v) && v.length >= 20,
    expected: 'sk-ant- prefix',
  },
  STRIPE_SECRET_KEY: {
    description: 'Stripe secret key',
    // sk-live- = production, sk-test- = test mode; reject pk_ (publishable)
    test: (v) => /^sk_(live|test)_[A-Za-z0-9]+$/.test(v),
    expected: 'sk-live- or sk-test- prefix',
  },
  LOGFIRE_TOKEN: {
    description: 'Logfire ingestion token',
    test: (v) => typeof v === 'string' && v.length >= 16,
    expected: 'non-empty token, >=16 chars',
  },
};

function validateEnv(env = process.env) {
  const errors = [];
  for (const [name, rule] of Object.entries(VALIDATORS)) {
    const value = env[name];
    if (value === undefined || value === '') {
      errors.push(`${name}: missing (expected ${rule.expected})`);
      continue;
    }
    if (!rule.test(value)) {
      // Note: we deliberately do NOT include the value in the error.
      errors.push(`${name}: invalid format (expected ${rule.expected})`);
    }
  }
  return errors;
}

if (require.main === module) {
  const errors = validateEnv();
  if (errors.length > 0) {
    console.error('Environment validation failed:');
    for (const e of errors) console.error('  -', e);
    process.exit(1);
  }
  console.log('Environment validation passed.');
}

module.exports = { validateEnv, VALIDATORS };

